import {expect,test} from 'bun:test'
import {createPostgresConnection,HostedWorkspaceDatabase} from '../../packages/neuvetra-database/src/hosted'
import {M71_ARTIFACT} from '../../packages/neuvetra-database/src/m71-contract'
import {decodeCorporateRegister} from '../../apps/site-web/src/lib/m71-api'
import type {WorkspaceConnection} from '../../packages/neuvetra-database/src/workspace'
const runtimeUrl=process.env.M71_QA_PIN_DATABASE_URL
if(runtimeUrl!=='postgres://neuvetra_runtime@127.0.0.1:55463/m71_qa_parity_restore')throw Error('Explicit isolated restored QA database required')
const fixture=await Bun.file(new URL('./m71-qa-native-fixture.json',import.meta.url)).json()
test('restored native reader checks bundled synthetic evidence bytes and recovers after in-process fixture tamper',async()=>{
 const connection=createPostgresConnection(runtimeUrl,{tls:false}),db=new(HostedWorkspaceDatabase as unknown as new(c:WorkspaceConnection,r:string)=>HostedWorkspaceDatabase)(connection,'abcdefghijklmnopqrst')
 const original=M71_ARTIFACT.text
 try{
  const valid=await db.findCorporateInventory(fixture.actorIds.owner,fixture.company);expect(valid).toEqual(fixture.register);await decodeCorporateRegister(valid,fixture.company)
  ;(M71_ARTIFACT as unknown as {text:string}).text=original+' tampered fixture text'
  let failed=false;try{await db.findCorporateInventory(fixture.actorIds.owner,fixture.company)}catch{failed=true}expect(failed).toBe(true)
  ;(M71_ARTIFACT as unknown as {text:string}).text=original
  expect(await db.findCorporateInventory(fixture.actorIds.owner,fixture.company)).toEqual(valid)
 }finally{(M71_ARTIFACT as unknown as {text:string}).text=original;await db.close()}
})

import {expect,test} from 'bun:test'
import {createM71Seed,M71_MAX_VERSIONS,M71_ARTIFACT,M71_CATEGORIES,M71_LIMITATIONS} from '../../packages/neuvetra-database/src/m71-contract'
const fixture=await Bun.file(new URL('./m71-qa-native-fixture.json',import.meta.url)).json()
const source=await Bun.file(new URL('../../apps/site-web/src/components/CorporateCoverageRegister.tsx',import.meta.url)).text()
const script=new Bun.Transpiler({loader:'tsx',tsconfig:{compilerOptions:{jsx:'react',jsxFactory:'h'}}}).transformSync(source.replace(/^import [^\n]+\n/gm,'').replace('export function CorporateCoverageRegister','function CorporateCoverageRegister'))+'\nreturn CorporateCoverageRegister'

// Exercises the actual component handlers with injected hooks/transport. Not a React DOM/browser test.
function harness(register=fixture.register,role='owner'){
 const slots:any[]=[],cleanups:Array<()=>void>=[];let cursor=0,first=true,tree:any,lastPayload:any
 const h=(type:any,props:any,...children:any[])=>({type,props:props??{},children})
 const names=['useCallback','useEffect','useRef','useState','corporateRegisterRequest','corporateSaveRequest','corporateReviewRequest','corporateExportRequest','syntheticCoverageReference','createM71Seed','M71_MAX_VERSIONS','M71_ARTIFACT','M71_CATEGORIES','M71_LIMITATIONS','h','React']
 const component=new Function(...names,script)((fn:any)=>{cursor++;return fn},(fn:()=>()=>void)=>{cursor++;if(first)cleanups.push(fn())},(v:any)=>{const n=cursor++;return slots[n]??(slots[n]={current:v})},(v:any)=>{const n=cursor++;if(!(n in slots))slots[n]=typeof v==='function'?v():v;return[slots[n],(next:any)=>{slots[n]=typeof next==='function'?next(slots[n]):next}]},async()=>register,async(_a:any,_c:any,_i:any,p:any)=>{lastPayload=structuredClone(p);return register.versions.at(-1)},async()=>null,async()=>fixture.initialExport,async()=>({}),createM71Seed,M71_MAX_VERSIONS,M71_ARTIFACT,M71_CATEGORIES,M71_LIMITATIONS,h,{Fragment:'fragment'})
 const actor={userId:fixture.actorIds.owner,role,accessToken:'synthetic-ui-only'}
 const render=()=>{cursor=0;tree=component({actor,workspaceId:fixture.company,headingRef:{current:null}});first=false}
 const flatten=(n:any):any[]=>n&&typeof n==='object'&&'type'in n?[n,...n.children.flat(Infinity).flatMap(flatten)]:[]
 const nodes=()=>flatten(tree)
 const text=(n:any):string=>n&&typeof n==='object'&&'children'in n?n.children.flat(Infinity).map(text).join(' ').replace(/\s+/g,' ').trim():typeof n==='string'||typeof n==='number'?String(n):''
 const button=(label:string)=>nodes().find(n=>n.type==='button'&&text(n).includes(label))
 const field=(label:string,type:string)=>{const group=nodes().find(n=>n.type==='label'&&text(n).startsWith(label));return group?flatten(group).find(n=>n.type===type):undefined}
 async function flush(){for(let i=0;i<20;i++)await Promise.resolve();render()}
 render();return{render,flush,nodes,text:()=>text(tree),button,field,payload:()=>lastPayload,cleanup:()=>cleanups.forEach(fn=>fn?.())}
}

test('saved findings identify categories and entities instead of generic repeated sentences',async()=>{
 const h=harness();await h.flush()
 expect(h.text()).toContain('Synthetic Juniper California')
 expect(h.text()).toContain('Franchises · Company-wide screening')
 expect(h.text()).toContain('Purchased electricity')
 expect(h.text()).toContain('Purchased electricity · Purchased electricity · Synthetic California office')
 h.cleanup()
})

test('switching explicit zero to missing clears hidden quantity and unit in actual save handler',async()=>{
 const h=harness();await h.flush();h.button('Make a correction').props.onClick();h.render();h.button('Scope 1, 2 and 3').props.onClick();h.render()
 h.button('Purchased electricity · Synthetic California office').props.onClick();h.render()
 expect(h.field('Activity data','select').props.value).toBe('explicit_zero')
 h.field('Activity data','select').props.onChange({target:{value:'missing'}});h.render()
 h.field('Reason for correction','textarea').props.onChange({target:{value:'Return synthetic zero to explicitly missing activity'}});h.render()
 const form=h.nodes().find(n=>n.type==='form'&&h.nodes().includes(n)&&n.children.flat(Infinity).some((c:any)=>c?.type==='h2'&&c.children.join('').startsWith('Save correction')))
 expect(Boolean(form)).toBe(true);form.props.onSubmit({preventDefault(){}});await h.flush()
 const row=h.payload().snapshot.coverageItems.find((c:any)=>c.sourceId!==null&&c.entityId===createM71Seed().entities[0]!.id)
 expect(row.activityDataState).toBe('missing');expect(row.quantity).toBeNull();expect(row.unit).toBeNull();h.cleanup()
})

test('member cannot start a correction and version limit explains saved-record availability',async()=>{
 const member=harness(fixture.register,'member');await member.flush();expect(member.button('Make a correction')).toBeUndefined();expect(member.text()).toContain('Read-only member access');member.cleanup()
 const many=structuredClone(fixture.register);while(many.versions.length<40)many.versions.push(structuredClone(many.versions.at(-1)))
 const bounded=harness(many);await bounded.flush();expect(bounded.button('Make a correction').props.disabled).toBe(true);expect(/40\s*-version limit/.test(bounded.text())).toBe(true);expect(bounded.text()).toContain('Saved versions remain available');bounded.cleanup()
})

import {expect,test} from 'bun:test'
import {createM71Seed,M71_ARTIFACT,m71Id} from '../../packages/neuvetra-database/src/m71-contract'
import {validateM71Snapshot,deriveM71Findings,m71CanonicalJson,parseM71Json,M71_EVIDENCE_SHA256} from '../../packages/neuvetra-database/src/m71-validation'

const ref=()=>({artifactId:M71_ARTIFACT.id,expectedSha256:M71_EVIDENCE_SHA256,locator:M71_ARTIFACT.locator,purpose:'Independent synthetic screening basis'})

test('California default preserves all group and source screens; reordered sets normalize equally',()=>{
 const seed=createM71Seed(),parsed=validateM71Snapshot(seed)
 expect(parsed.entities.every(e=>e.countryCode==='US'&&e.regionCode==='CA')).toBe(true)
 expect(parsed.coverageItems.filter(c=>c.domain.startsWith('scope3_'))).toHaveLength(15)
 const changed=structuredClone(seed);changed.entities.reverse();changed.coverageItems.reverse();changed.companyLabel=' '+seed.companyLabel+' '
 expect(m71CanonicalJson(validateM71Snapshot(changed))).toBe(m71CanonicalJson(parsed))
})

test('NA and exclusion require rationale plus pinned support at boundary and screening submission',()=>{
 for(const field of ['coverageItems','boundaryDecisions'] as const)for(const disposition of ['not_applicable','excluded'] as const)for(const omission of ['reason','evidence'] as const){
  const s=createM71Seed(),row=s[field][0]!
  row.disposition=disposition;row.reason=omission==='reason'?null:'Independent proposed screening finding';row.evidenceRefs=omission==='evidence'?[]:[ref()]
  expect(()=>validateM71Snapshot(s),`${field}/${disposition}/${omission}`).toThrow()
 }
})

test('unknown never becomes zero; explicit zero requires unit, reason and support',()=>{
 const seed=validateM71Snapshot(createM71Seed());expect(seed.coverageItems[0]!.quantity).toBeNull()
 for(const omission of ['basis','unit','evidence']){const s=createM71Seed(),r=s.coverageItems[0]!;r.quantity='0';r.unit=omission==='unit'?null:'kWh';r.activityDataState='explicit_zero';r.reason=omission==='basis'?null:'Recorded zero in synthetic exercise';r.evidenceRefs=omission==='evidence'?[]:[ref()];expect(()=>validateM71Snapshot(s)).toThrow()}
})

test('malformed or missing category and source universe is rejected',()=>{
 for(const edit of [(s:any)=>s.coverageItems.splice(s.coverageItems.findIndex((c:any)=>c.domain==='scope3_15'),1),(s:any)=>s.coverageItems.find((c:any)=>c.domain==='scope3_15').domain='scope3_16',(s:any)=>s.coverageItems.push({...s.coverageItems[0],id:m71Id(600)}),(s:any)=>s.coverageItems.splice(s.coverageItems.findIndex((c:any)=>c.sourceId!==null),1),(s:any)=>s.sources.pop()]){const s=createM71Seed();edit(s);expect(()=>validateM71Snapshot(s)).toThrow()}
})

test('unsupported discovered location remains visible and interval cycles fail',()=>{
 const s=createM71Seed();s.entities[1]!.regionCode='NV';s.facilities[1]!.regionCode='NV';const parsed=validateM71Snapshot(s)
 expect(parsed.entities[1]!.regionCode).toBe('NV');expect(deriveM71Findings(parsed).filter(f=>f.code==='unsupported_geography')).toHaveLength(2)
 const cycle=createM71Seed();cycle.relationships.push({...cycle.relationships[0]!,id:m71Id(610),parentEntityId:cycle.entities[1]!.id,childEntityId:cycle.entities[0]!.id});expect(()=>validateM71Snapshot(cycle)).toThrow()
})

test('prior registered records cannot disappear and fabricated evidence or client conclusions fail',()=>{
 const previous=createM71Seed(),next=structuredClone(previous);next.requirements=[];expect(()=>validateM71Snapshot(next,previous)).toThrow()
 for(const edit of [(s:any)=>s.coverageItems[0].evidenceRefs=[{...ref(),locator:'invented-page'}],(s:any)=>s.coverageItems[0].methodReadiness='released_for_use',(s:any)=>s.corporateCompleteness='complete',(s:any)=>s.requirements[0].applicability='applicable']){const s=createM71Seed();edit(s);expect(()=>validateM71Snapshot(s)).toThrow()}
 expect(()=>parseM71Json('{"a":1,"a":2}')).toThrow()
 expect(()=>parseM71Json('{"outer":{"x":1,"x":2}}')).toThrow()
})

test('omitted expected parent relationship is rejected or explicitly reported unknown',()=>{
 const s=createM71Seed();s.relationships=[]
 let rejected=false,findings:any[]=[]
 try{findings=deriveM71Findings(validateM71Snapshot(s))}catch{rejected=true}
 expect(rejected||findings.some(f=>/relationship|hierarchy|control/.test(f.code))).toBe(true)
})

test('location fields require scalar strings, never coercible arrays or objects',()=>{
 for(const collection of ['entities','facilities'] as const)for(const field of ['countryCode','regionCode'] as const)for(const value of [['US'],['CA'],{toString:()=>field==='countryCode'?'US':'CA'}]){
  const s=createM71Seed();(s[collection][0] as any)[field]=value
  expect(()=>validateM71Snapshot(s)).toThrow()
 }
})

import { expect, test } from "bun:test"
import { corporateRegisterRequest } from "../../apps/site-web/src/lib/m71-api"
import { createM71Seed, M71_ARTIFACT, M71_CATEGORIES, M71_LIMITATIONS, M71_PROFILE, M71_MAX_VERSIONS } from "../../packages/neuvetra-database/src/m71-contract"

const company="71111111-1111-4111-8111-111111111111",user="72222222-2222-4222-8222-222222222222"
const empty=()=>({profile:M71_PROFILE,companyId:company,inventoryId:null,headVersionId:null,versions:[],limitations:[...M71_LIMITATIONS]})
function deferred<T>(){let resolve!:(v:T)=>void;const promise=new Promise<T>(r=>{resolve=r});return {promise,resolve}}
const actor=(controller:AbortController,callback=()=>{})=>({userId:user,role:"owner" as const,accessToken:"synthetic-test-token",signal:controller.signal,onUnauthorized:callback})

test("actual coverage adapter refuses late headers and body after actor lifetime abort without revoking a replacement",async()=>{
 const original=globalThis.fetch
 try{
  for(const stage of ["headers","body"]){
   const control=new AbortController(),pending=deferred<any>();let unauthorized=0
   globalThis.fetch=(async(_url,init)=>{expect(init?.signal).toBe(control.signal);expect(init?.cache).toBe("no-store");return stage==="headers"?pending.promise:{ok:true,status:200,text:()=>pending.promise}}) as typeof fetch
   const result=corporateRegisterRequest(actor(control,()=>{unauthorized++}),company).then(()=>"accepted",()=>"aborted")
   await Promise.resolve();control.abort();pending.resolve(stage==="headers"?new Response("",{status:403}):JSON.stringify(empty()))
   expect(await result).toBe("aborted");expect(unauthorized).toBe(0)
  }
 }finally{globalThis.fetch=original}
})

test("actual coverage adapter rejects duplicate keys and foreign-company response and accepts fresh authorized response",async()=>{
 const original=globalThis.fetch
 try{
  for(const content of [JSON.stringify({...empty(),companyId:user}),JSON.stringify(empty()).replace('"profile":','"companyId":"'+user+'","profile":')]){
   globalThis.fetch=(async()=>new Response(content)) as typeof fetch
   await expect(corporateRegisterRequest(actor(new AbortController()),company)).rejects.toThrow()
  }
  globalThis.fetch=(async()=>Response.json(empty())) as typeof fetch
  expect(await corporateRegisterRequest(actor(new AbortController()),company)).toEqual(empty())
 }finally{globalThis.fetch=original}
})

// Execute the actual component with injected React hooks/network and JSX values.
// This checks stale callbacks and draft lifetime, not browser DOM/focus behavior.
const source=await Bun.file(new URL("../../apps/site-web/src/components/CorporateCoverageRegister.tsx",import.meta.url)).text()
const script=new Bun.Transpiler({loader:"tsx",tsconfig:{compilerOptions:{jsx:"react",jsxFactory:"h",jsxFragmentFactory:"Fragment"}}}).transformSync(source.replace(/^import[^\r\n]*(?:\r?\n|$)/gm,"").replace("export function CorporateCoverageRegister","function CorporateCoverageRegister"))+"\nreturn CorporateCoverageRegister"
function componentHarness(request:()=>Promise<any>,role="owner"){
 const slots:any[]=[],effects:Array<()=>void>=[],cleanups:Array<()=>void>=[];let cursor=0,first=true,updates=0,tree:any
 const controller=new AbortController(),currentActor={...actor(controller),role}
 const h=(type:any,props:any,...children:any[])=>({type,props:props??{},children})
